L["Discord"] = "Discord"
L["Easy Stealth"] = "Sigilo fácil"
L["Enable "] = "Activar "
L["Enable/disable any time via the options panel sidebar."] = "Actívalo o desactívalo cuando quieras desde la barra lateral del panel de opciones."
L["Enables sharpening to improve image clarity. Especially noticeable at lower render scales."] = "Activa la nitidez para mejorar la claridad de la imagen. Se nota sobre todo con escalas de renderizado bajas."
L["Havoc"] = "Devastación"
L["Hides the EllesmereUI button from the game's Escape/pause menu."] = "Oculta el botón de EllesmereUI del menú de Esc/pausa del juego."
L["Hides the sync icons on the sidebar module list."] = "Oculta los iconos de sincronización de la lista de módulos de la barra lateral."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Oculta el botón del modo desbloqueo del menú de Esc/pausa del juego. Puedes seguir activándolo desde el panel de opciones de EUI."
L["Import the anchor & size-match relationships from this profile. Off = keep your own layout; only the selected modules' own positions/settings come in."] = "Importa las relaciones de anclaje y de igualar tamaño de este perfil. Desactivado = mantienes tu propio diseño; solo entran las posiciones y ajustes propios de los módulos elegidos."
L["In Maintenance"] = "En mantenimiento"
L["Include the anchor & size-match relationships between modules. Off = export each module's own positions only, with no cross-module tying."] = "Incluye las relaciones de anclaje y de igualar tamaño entre módulos. Desactivado = solo exporta las posiciones propias de cada módulo, sin uniones entre módulos."
L["Keybinds respond on key down instead of key up. This helps make your abilities feel more responsive."] = "Los atajos responden al pulsar la tecla en lugar de al soltarla. Así tus habilidades se sienten más rápidas."
L["Never miss an update again. The new Patch Notes section breaks down what's new each release, with quick links straight to every new setting."] = "No te vuelvas a perder una actualización. La nueva sección de notas del parche explica las novedades de cada versión, con enlaces directos a cada ajuste nuevo."
L["No conditional overrides yet. Click the Conditional Overrides button next to the module search bar and create a conditional group (Dungeon, Raid, Keybind...). Spec overrides always take precedence over conditionals."] = "Aún no hay ajustes condicionales. Haz clic en el botón Ajustes condicionales junto a la barra de búsqueda del módulo y crea un grupo condicional (mazmorra, banda, atajo...). Los ajustes por especialización siempre tienen prioridad sobre los condicionales."
L["No other profiles to sync to"] = "No hay otros perfiles con los que sincronizar"
L["No Profile Level Customizations"] = "Sin personalizaciones a nivel de perfil"
L["Patreon"] = "Patreon"
L["PayPal"] = "PayPal"
L["Pet Move"] = "Mover la mascota"
L["Prevents Blizzard from dimming Swiftmend on action bars and CDM based on Efflorescence state."] = "Evita que Blizzard atenúe Alivio presto en las barras de acción y en el CDM según el estado de Floración."
L["Reset to default"] = "Restablecer valores"
L["Sets the accent color used across all EllesmereUI elements (tabs, glows, highlights, borders). Defaults to your theme color."] = "Elige el color de acento de todos los elementos de EllesmereUI (pestañas, brillos, resaltados, bordes). Por defecto, el color de tu tema."
L["Show a pulsing dot on the Patch Notes button whenever EllesmereUI updates to a new version."] = "Muestra un punto que parpadea en el botón de notas del parche cada vez que EllesmereUI se actualiza a una versión nueva."
L["Slug outline renders higher quality outlines compared to the base WoW outline mode but may make outline effects appear slightly thicker."] = "El contorno Slug dibuja contornos de más calidad que el modo de contorno básico de WoW, pero puede hacer que se vean un poco más gruesos."
L["Spirit Mend"] = "Aliviar espíritu"
L["Swatch 1"] = "Muestra 1"
L["Swatch 2"] = "Muestra 2"
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "El gestor de tiempos de reutilización hace mucho más que mostrarlos: también tiene ajustes por hechizo, brillos de barras, barras de seguimiento ¡y más! Echa un vistazo a algunos trucos para sacarle más partido."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "El idioma del panel de opciones de EllesmereUI. Automático sigue el de tu juego. Lo que no está traducido sale en inglés."
L["the Randomly trigger"] = "el activador Al azar"
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Estos ajustes priorizan la fluidez y la claridad visual sobre el detalle del entorno. Las texturas se quedan en alta calidad para que tu personaje y el mundo se sigan viendo perfectos."
L["This bar will only show if you have an enemy targeted"] = "Esta barra solo se muestra si tienes un enemigo como objetivo"
L["This element doesn't support both Height and Width matching"] = "Este elemento no permite igualar la altura y la anchura a la vez"
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity."] = "Esta función optimiza los ajustes gráficos del juego para darte la mejor combinación de muchos FPS y claridad visual."
L["This feature requires Snap Elements to be enabled"] = "Esta función necesita que esté activado ajustar elementos"
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Esta es la ventana de cola de hechizos: evita que puedas encadenar demasiados hechizos a la vez, lo que hace que el juego parezca ir con retraso. Lo recomendado suele ser un mínimo de 200 + tu ping. Si no tienes claro qué hace este ajuste, déjalo en 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Aquí controlas los ajustes del modo desbloqueo.\n\nLos elementos se recolocan arrastrándolos o con las flechas (+Mayús)\nAncla, iguala la altura o iguala la anchura de cualquier elemento.\nSe ajusta al elemento más cercano, pero puedes ajustarlo solo a\n un elemento concreto con el clic derecho o el icono de ajustes."
L["This module can't be overridden. Exit the override editing session to open it."] = "Este módulo no admite ajustes propios. Sal de la edición de ajustes para abrirlo."
L["This option is only available for the Custom Color Theme"] = "Esta opción solo está disponible con el tema de color personalizado"
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Esta unidad usa el marco predeterminado de Blizzard: aquí no hay ajustes de EllesmereUI que configurar."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "El marco de esta unidad está oculto: aquí no hay ajustes de EllesmereUI que configurar."
L["Toggle EllesmereUI"] = "Mostrar/ocultar EllesmereUI"
L["Toggle EllesmereUI's optional buttons: the Escape menu buttons and the minimap button."] = "Muestra u oculta los botones opcionales de EllesmereUI: los del menú de Esc y el botón del minimapa."
L["Track consumables and raid buffs for instanced content."] = "Controla los consumibles y los beneficios de banda en el contenido en estancia."
L["Twitch"] = "Twitch"
L["Unlock Mode is how you move and resize everything in EllesmereUI, and it is packed with tools: anchors, width matching, fallback anchors, per-group layouts. This video gets you fluent fast."] = "El modo desbloqueo es la forma de mover y cambiar de tamaño todo en EllesmereUI, y está lleno de herramientas: anclajes, igualar anchura, anclajes alternativos, diseños por grupo. Con este vídeo lo dominarás enseguida."
L["WARNING: This feature requires you to re-log or restart WoW to take effect."] = "AVISO: esta función necesita volver a conectarse o reiniciar WoW para aplicarse."
L["You changed settings while profile sync is active. Please reload your UI for sync changes to take effect."] = "Has cambiado ajustes con la sincronización de perfiles activa. Recarga la interfaz para que se apliquen los cambios de sincronización."
L["Your current spec has an assigned profile so you cannot switch to another. Please unassign to switch."] = "Tu especialización actual tiene un perfil asignado, así que no puedes cambiar a otro. Quita la asignación para cambiar."
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29dClic izquierdo:|r |cffE0E0E0Mostrar/ocultar EllesmereUI|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29dClic central:|r |cffE0E0E0Ocultar el botón del minimapa|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29dClic derecho:|r |cffE0E0E0Entrar en el modo desbloqueo|r"
L["Better Character Panel conflicts with the EllesmereUI's Character Sheet. Disable either Better Character Panel or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Better Character Panel choca con la hoja de personaje de EllesmereUI. Desactiva Better Character Panel o el aspecto de la hoja de personaje en los ajustes de Blizz UI Enhanced."
L["Blizzard's Edit Mode snapping may not work correctly until you reload your UI."] = "Puede que el ajuste del modo edición de Blizzard no funcione bien hasta que recargues la interfaz."
L["Changing cursor anchor requires a UI reload to take effect."] = "Cambiar el anclaje del cursor necesita recargar la interfaz."
L["Changing quest icons requires a UI reload to apply."] = "Cambiar los iconos de misión necesita recargar la interfaz."
L["Changing the frame source requires a UI reload to take effect."] = "Cambiar el origen del marco necesita recargar la interfaz."
L["Changing the language requires a UI reload."] = "Cambiar el idioma necesita recargar la interfaz."
L["Chonky Character Sheet conflicts with the EllesmereUI's Character Sheet. Disable either Chonky or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Chonky Character Sheet choca con la hoja de personaje de EllesmereUI. Desactiva Chonky o el aspecto de la hoja de personaje en los ajustes de Blizz UI Enhanced."
L["Combat text font changes require a logout to character select to take effect. This is a WoW engine limitation."] = "Los cambios en la fuente del texto de combate necesitan salir a la selección de personaje para aplicarse. Es una limitación del motor de WoW."
L["Deja Character Stats conflicts with the EllesmereUI's Character Sheet. Disable either Deja or the Character Sheet skin in Blizzard UI Enhanced settings."] = "Deja Character Stats choca con la hoja de personaje de EllesmereUI. Desactiva Deja o el aspecto de la hoja de personaje en los ajustes de Blizz UI Enhanced."
L["Enable & Reload"] = "Activar y recargar"
L["Enter a name for the new profile:"] = "Escribe un nombre para el perfil nuevo:"
L["Include CDM Spell Layout?"] = "¿Incluir el diseño de hechizos del CDM?"
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Incluye el diseño de hechizos de tu gestor de tiempos de reutilización (qué hechizos van en qué barras) y todos los ajustes por hechizo de las especializaciones que elijas."
L["Leatrix Plus has chat and minimap features that conflict with EllesmereUI. Disable any chat or minimap related options within Leatrix Plus to stay compatible."] = "Leatrix Plus tiene funciones de chat y minimapa que chocan con EllesmereUI. Desactiva en Leatrix Plus cualquier opción del chat o del minimapa para que sean compatibles."
L["Many of ElvUI's modules are incompatible with EllesmereUI. Make sure to disable any conflicting modules."] = "Muchos módulos de ElvUI no son compatibles con EllesmereUI. Asegúrate de desactivar los que choquen."
L["Reset All & Reload"] = "Restablecer todo y recargar"
L["Save & Exit"] = "Guardar y salir"
L["TellMeWhen overlaps with EllesmereUI's core positional architecture. If you ONLY use for sound alerts it should be okay but may still cause issues."] = "TellMeWhen se solapa con el sistema de posiciones de EllesmereUI. Si SOLO lo usas para avisos de sonido no debería haber problema, pero aun así puede dar fallos."
L["This frame's source changes require a UI reload to take effect."] = "Los cambios de origen de este marco necesitan recargar la interfaz."
L["You have unsaved position changes.\nWhat would you like to do?"] = "Tienes cambios de posición sin guardar.\n¿Qué quieres hacer?"
L["%1$s Module"] = "Módulo %1$s"
L["A profile named \"%1$s\" already exists. Please choose a different name."] = "Ya existe un perfil llamado «%1$s». Elige otro nombre."
L["Anchor to %1$s"] = "Anclar a %1$s"
L["Are you sure you want to %1$s %2$s?"] = "¿Seguro que quieres %1$s %2$s?"
L["Are you sure you want to reset all %1$s settings to their defaults? This will reload your UI."] = "¿Seguro que quieres devolver todos los ajustes de %1$s a sus valores predeterminados? Esto recargará la interfaz."
L["Export will include %1$s of %2$s addons."] = "La exportación incluirá %1$s de %2$s addons."
L["Import will include %1$s of %2$s addons."] = "La importación incluirá %1$s de %2$s addons."
L["Importing %1$s"] = "Importando %1$s"
L["Keybind: %1$s"] = "Atajo: %1$s"
L["Linked by Anchor/Width/Height Matching to: %1$s. These export together."] = "Unido por anclaje o por igualar anchura/altura a: %1$s. Se exportan juntos."
L["Linked by Anchor/Width/Height Matching to: %1$s. These import together."] = "Unido por anclaje o por igualar anchura/altura a: %1$s. Se importan juntos."
L["Resolution Issue: Profile was made at %1$dx%2$d, yours is %3$dx%4$d"] = "Problema de resolución: el perfil se hizo a %1$dx%2$d y la tuya es %3$dx%4$d"
L["Select which specs you want %1$s to be assigned to"] = "Elige a qué especializaciones quieres asignar %1$s"
L["Snap Target: %1$s"] = "Destino del ajuste: %1$s"
L["Snap to: %1$s"] = "Ajustar a: %1$s"
L["'%s' is now customized for %s."] = "«%s» ahora está personalizado para %s."
L["After anchoring, drag to an edge and choose a grow direction to maintain its corner spot as bars change size."] = "Después de anclar, arrástralo a un borde y elige una dirección de crecimiento para que se quede en su esquina cuando las barras cambien de tamaño."
L["Assign this profile to the same specializations it was assigned to on export. Off = your current spec assignments stay as they are."] = "Asigna este perfil a las mismas especializaciones que tenía al exportarlo. Desactivado = tus asignaciones actuales se quedan como están."
L["Auto Assign to Specs"] = "Asignar automáticamente a especializaciones"
L["Beacon Reminders"] = "Recordatorios de Señal"
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique controla el lanzamiento con clic en los mismos marcos de banda que el HoverCast de EllesmereUI, así que chocan. Desactiva el addon Clique para usar HoverCast."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "Los colores se comparten de forma global desde el perfil «%1$s».\nCambia a él (o pon Tomar los colores de en este perfil) para editarlos."
L["Coming Soon"] = "Próximamente"
L["Conditional"] = "Condicional"
