L["Recolors the frame border in the threat color while the unit has aggro instead of drawing a separate border."] = "Cambia el color del borde del marco al color de amenaza mientras la unidad tiene el aggro, en lugar de dibujar un borde aparte."
L["Adds the Default Blizz Frames glow line where the shield meets current health."] = "Añade la línea de brillo de los marcos predeterminados de Blizzard donde el escudo se junta con la salud actual."
