L["EllesmereUI could not save this change to your Edit Mode layout, so it has to be set by hand. The Cooldown Manager has to be off while you do it, because it hides Blizzard's cooldown viewers and a hidden viewer cannot be selected in Edit Mode.\n\n"] = "EllesmereUI no ha podido guardar este cambio en tu diseño del modo edición, así que hay que ponerlo a mano. El gestor de reutilizaciones tiene que estar desactivado mientras lo haces, porque oculta los visores de reutilizaciones de Blizzard y un visor oculto no se puede seleccionar en el modo edición.\n\n"
L["This will keep appearing each login until the layout is correct."] = "Esto seguirá saliendo cada vez que entres hasta que el diseño esté bien."
L["This bar has an Additional Bar Offset (X %1$s, Y %2$s) set in its options. Unlock mode shows the base position; the offset re-applies when you exit."] = "Esta barra tiene un desplazamiento adicional (X %1$s, Y %2$s) en sus opciones. El modo desbloqueo muestra la posición base; el desplazamiento se vuelve a aplicar al salir."
