L["Show the FocusKick bar on your current target's nameplate instead of your focus target's nameplate."] = "Muestra la barra de FocusKick en la placa de nombre de tu objetivo actual en lugar de en la de tu foco."
L["Show Tooltip on Hover"] = "Mostrar descripción al pasar el ratón"
L["Stack Threshold"] = "Umbral de acumulaciones"
L["Thickness of any Pixel Glow assigned to this bar's buttons. Assign glows by right-clicking an icon in the preview."] = "Grosor de cualquier brillo de píxeles asignado a los botones de esta barra. Asigna brillos con clic derecho en un icono de la vista previa."
L["This option is not available for custom shaped icons"] = "Esta opción no está disponible para iconos con forma personalizada"
L["This option requires a Duration Text position other than None"] = "Esta opción necesita una posición del texto de duración distinta de Ninguna"
L["This option requires a Name Text position other than None"] = "Esta opción necesita una posición del texto del nombre distinta de Ninguna"
L["This option requires a Stacks Text position other than None"] = "Esta opción necesita una posición del texto de acumulaciones distinta de Ninguna"
L["This option requires exactly 2 rows"] = "Esta opción necesita exactamente 2 filas"
L["This option requires Fill Color to be set to Custom"] = "Esta opción necesita que el color de relleno esté en Personalizado"
L["This spell is already being used on "] = "Este hechizo ya se usa en "
L["This will change the color of your bar if you have more than your chosen number of stacks"] = "Cambia el color de la barra si tienes más acumulaciones que el número elegido"
L["This will display the word \"FOCUS\" below caster/miniboss mobs in M+ if you have not set your focus. Disabled for specs with no kick."] = "Muestra la palabra «FOCO» debajo de los lanzadores de hechizos y minijefes en M+ si no has puesto foco. Desactivado en especializaciones sin interrupción."
L["When you press an ability's keybind, show the action button's \"pushed down\" look on its icon on this bar -- even while the ability is on cooldown."] = "Al pulsar el atajo de una facultad, muestra el aspecto de «botón pulsado» del botón de acción en su icono de esta barra, aunque la facultad esté en reutilización."
