L["Delete Preset"] = "Borrar plantilla"
L["Delete this global group for all specs"] = "Borra este grupo global en todas las especializaciones"
L["Dims this bar while out of combat."] = "Atenúa esta barra fuera de combate."
L["Disabled while Always Show Buffs is enabled (on the bar, or on any individual buff)"] = "Desactivado mientras Mostrar siempre los beneficios está activado (en la barra o en algún beneficio concreto)"
L["Eases bar movement instead of snapping. Affects all Tracking Bars of that type, in every spec of this profile."] = "Mueve la barra con suavidad en lugar de a saltos. Afecta a todas las barras de seguimiento de ese tipo, en todas las especializaciones de este perfil."
L["Global Group"] = "Grupo global"
L["Horizontal Orientation (name text is not shown on vertical bars)"] = "Orientación horizontal (el texto del nombre no se muestra en barras verticales)"
