L["Second Row Icon Size"] = "Tamaño de icono de la segunda fila"
L["How extra rows grow when the second row appears or disappears. Grow Down keeps the top row in place, Grow Up keeps the bottom row in place, Grow Centered keeps the bar centered."] = "Cómo crecen las filas extra cuando aparece o desaparece la segunda fila. Crecer hacia abajo deja la fila de arriba en su sitio, Crecer hacia arriba deja la fila de abajo en su sitio y Crecer centrado mantiene la barra centrada."
L["Hide this bar's icons and show only the duration text."] = "Oculta los iconos de esta barra y muestra solo el texto de duración."
L["Only Show Numbers"] = "Mostrar solo números"
L["Screen layer this bar and its icons render on."] = "Capa de la pantalla en la que se dibujan esta barra y sus iconos."
