L["Not available in Dark Mode. Dark Mode colors can be adjusted in Global Settings -> Colors."] = "No disponible en el modo oscuro. Los colores del modo oscuro se cambian en Ajustes globales -> Colores."
L["+ Add Threshold"] = "+ Añadir umbral"
L["Choose which specs sync with %1$s, including your alts' specs (the source is always included)"] = "Elige qué especializaciones se sincronizan con %1$s, también las de tus otros personajes (el origen siempre está incluido)"
L["Color the bar differently at several stack counts. The highest count you have reached wins."] = "Pon a la barra un color distinto según el número de acumulaciones. Manda el número más alto que hayas alcanzado."
