L["Maximum of 5 thresholds."] = "Máximo de 5 umbrales."
L["Slot ID"] = "ID del hueco"
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "Sincronizando reutilizaciones y beneficios genéricos en %d especializaciones. El orden de los iconos no se sincroniza: cada especialización mantiene el suyo."
L["The single stack threshold is off while Multiple Thresholds is on."] = "El umbral de acumulaciones único está desactivado mientras Varios umbrales está activado."
L["This setting's active Apply to Bar (All Specs) value will be replaced."] = "Se sustituirá el valor activo de Aplicar a la barra (todas las especializaciones) de este ajuste."
