L["Use Multiple Thresholds"] = "Usar varios umbrales"
L["Fill Up"] = "Llenar hacia arriba"
L["Mirrors which end of the bar the fill is anchored to. It does not change the direction the bar travels: use Fill Up for that."] = "Cambia el extremo de la barra desde el que sale el relleno. No cambia la dirección en la que avanza la barra: para eso, usa Llenar hacia arriba."
L["Fills the bar as the cooldown recovers instead of draining it as the cooldown runs down."] = "Llena la barra según se recupera la reutilización en lugar de vaciarla según pasa."
L["Adjust Crop"] = "Ajustar recorte"
L["How much is trimmed from the icon's top and bottom, as a percentage per side. 10% is the classic cropped look."] = "Cuánto se recorta arriba y abajo del icono, en porcentaje por cada lado. Un 10% imita el aspecto recortado clásico."
L["Power Colored Background. Power colors can be adjusted in Global Settings -> Colors."] = "Fondo con color de poder. Los colores de poder se cambian en Ajustes globales -> Colores."
