L["Only shows the cursor circle while you are in combat."] = "Solo muestra el círculo del cursor mientras estás en combate."
L["Only shows the GCD circle while you are in combat."] = "Solo muestra el círculo del GCD mientras estás en combate."
L["Only shows the cast bar circle while you are in combat."] = "Solo muestra el círculo de la barra de hechizos mientras estás en combate."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Evita seleccionar con el clic derecho. Enemigos se aplica en todas partes. Aliados en combate solo lo evita con objetivos amistosos mientras estás en combate, para que puedas seguir haciendo clic derecho en mercaderes y PNJ fuera de combate.\n\nNota: mientras esté activo, mantener clic izquierdo + derecho para avanzar no funcionará si el cursor está sobre una placa de nombre o unidad bloqueada, porque esta función tiene que quedarse con todo el botón derecho del ratón para evitar la selección."
L["Edit the saved signup note."] = "Edita la nota de inscripción guardada."
L["Saved between reloads and relogs. In Group Finder, choose Copy, press Ctrl+C, then Ctrl+V."] = "Se guarda al recargar y al volver a entrar. En el buscador de grupos, elige Copiar, pulsa Ctrl+C y luego Ctrl+V."
L["Enter signup note..."] = "Escribe la nota de inscripción..."
L["Orbits the checked elements while Party Mode is active."] = "Hace girar los elementos marcados mientras el modo fiesta está activo."
L["Full-window modes only. Shows start as a small icon, and the keybind switches between the icon and the full windows."] = "Solo en los modos de ventana completa. Empieza como un icono pequeño, y el atajo cambia entre el icono y las ventanas completas."
L["Compact Band puts markers, ready check and pull timer in one resizable row. The other choices keep the original window layouts."] = "Banda compacta pone las marcas, la comprobación de listos y el temporizador de pull en una sola fila que puedes cambiar de tamaño. Las otras opciones mantienen la disposición original de las ventanas."
L["Full-window modes only. Which way the windows extend from the collapsed icon when they open."] = "Solo en los modos de ventana completa. Hacia dónde se despliegan las ventanas desde el icono al abrirse."
L["Adds a 'Train All' button next to the Train button at profession trainers, allowing you to learn all available skills with one click."] = "Añade un botón «Aprender todo» junto al botón Entrenar en los instructores de profesión, para aprender todas las habilidades disponibles con un clic."
L["Adds a Calc toggle button to the character sheet that opens and closes the Upgrade Calculator."] = "Añade a la hoja del personaje un botón Calc que abre y cierra la calculadora de mejoras."
L["After a successful instance reset, automatically announces it in party or raid chat so your group knows they can re-enter."] = "Tras reiniciar bien una instancia, lo avisa solo en el chat del grupo o de la banda para que tu grupo sepa que puede volver a entrar."
L["Always show the crosshair."] = "Mostrar siempre la cruz."
L["Auto Open Containers Settings"] = "Ajustes de abrir contenedores solo"
L["Auto Repair"] = "Reparación automática"
L["Automatically dismisses the 'new mount/pet/toy' fanfare notification when you receive one, so you don't have to click through the collections journal."] = "Cierra sola la notificación de «montura/mascota/juguete nuevo» cuando consigues uno, para que no tengas que pasar por el diario de colecciones."
L["Automatically enables the 'Current Expansion Only' filter whenever you open the Auction House."] = "Activa solo el filtro «Solo la expansión actual» cada vez que abres la casa de subastas."
L["Automatically inserts your key into the Font of Power."] = "Introduce sola tu piedra angular en la Font of Power."
L["Automatically opens and closes the Upgrade Calculator when the Character Sheet is opened or closed."] = "Abre y cierra sola la calculadora de mejoras al abrir o cerrar la hoja del personaje."
L["Automatically opens bags, boxes and parcels in your inventory when they are added to your bags."] = "Abre solos las bolsas, cajas y paquetes cuando entran en tus bolsas."
L["Hold Capped Artisan Payouts"] = "Guardar los pagos de artesano al tope"
L["Keeps Artisan's Consortium Payouts closed while Shard of Dundun is at its maximum, then resumes automatic opening after you spend shards."] = "Mantiene cerrados los Artisan's Consortium Payouts mientras Shard of Dundun está al máximo, y vuelve a abrirlos solos cuando gastas fragmentos."
L["Automatically opens the Upgrade Calculator when the Crest Upgrade NPC window is opened."] = "Abre sola la calculadora de mejoras al abrir la ventana del PNJ de mejora de emblemas."
L["Automatically removes cosmetic transforms when they are applied to you, such as profession gear, holiday costumes, toys and consumables. Use the cog to pick exactly which transforms are removed. Transforms applied during combat are removed when combat ends."] = "Quita solas las transformaciones de aspecto que te aplican, como el equipamiento de profesión, los disfraces de festividades, los juguetes y los consumibles. Usa el engranaje para elegir exactamente cuáles se quitan. Las que te aplican en combate se quitan al terminar el combate."
L["Automatically repair all gear when visiting a repair vendor."] = "Repara solo todo el equipo al visitar a un mercader que repare."
L["Automatically sell all junk items when visiting a vendor."] = "Vende sola toda la chatarra al visitar a un mercader."
L["Automatically starts and stops combat logging when entering or leaving a loggable instance."] = "Empieza y para solo el registro de combate al entrar o salir de una instancia que se pueda registrar."
L["Automatically types DELETE when throwing away a valuable item. Also allows you to press enter to accept the deletion."] = "Escribe solo BORRAR al tirar un objeto valioso. También te deja pulsar Intro para aceptar el borrado."
L["BattleRes Icon"] = "Icono de resurrección en combate"
L["Bloodlust Icon"] = "Icono de Ansia de sangre"
L["Cast Bar Circle"] = "Círculo de la barra de hechizos"
L["Changes the crosshair color when your current target is out of range."] = "Cambia el color de la cruz cuando tu objetivo actual está fuera de alcance."
L["Checked transforms are removed automatically when applied to you."] = "Las transformaciones marcadas se quitan solas cuando te las aplican."
L["Choose when the crosshair is shown."] = "Elige cuándo se ve la cruz."
L["Choose which transforms are removed"] = "Elige qué transformaciones se quitan"
L["Ctrl + Left-Click Drag for a temporary move that resets when the panel closes."] = "Ctrl + arrastrar con el clic izquierdo para moverlo solo hasta que se cierre el panel."
L["Delays stopping combat logging by 30 seconds after leaving an instance. Recommended for Warcraft Recorder compatibility."] = "Retrasa 30 segundos el final del registro de combate al salir de una instancia. Recomendado para que funcione bien con Warcraft Recorder."
L["Displays a crosshair at the center of the screen."] = "Muestra una cruz en el centro de la pantalla."
L["Displays a spoiler tag over guild chat in the communities window that you can click to hide"] = "Pone una tapa sobre el chat de la hermandad en la ventana de comunidades; haz clic en ella para ocultarlo"
L["Displays a ZZZ indicator on your player frame when you are in a resting area."] = "Muestra un indicador ZZZ en tu marco del jugador cuando estás en una zona de descanso."
L["Displays cursor and player coordinates at the bottom of the world map."] = "Muestra las coordenadas del cursor y del jugador en la parte de abajo del mapa del mundo."
L["Displays secondary stat percentages (Crit, Haste, Mastery, Vers) at the top left of the screen."] = "Muestra los porcentajes de las estadísticas secundarias (golpe crítico, celeridad, maestría, versatilidad) arriba a la izquierda de la pantalla."
L["Double-click a group listing to instantly sign up without pressing the Sign Up button."] = "Haz doble clic en un grupo de la lista para inscribirte al momento sin pulsar el botón Inscribirse."
L["Double-click a group listing to instantly sign up without pressing the Sign Up button. Hold Shift to keep the dialog open, e.g. to type a signup note."] = "Haz doble clic en un grupo de la lista para inscribirte al momento sin pulsar el botón Inscribirse. Mantén Mayús para que la ventana siga abierta, por ejemplo para escribir una nota."
L["Enable the crosshair to use this option."] = "Activa la cruz para usar esta opción."
L["Enables auto loot and hides the loot window when looting. Hold Shift when looting to show."] = "Activa el despojo automático y oculta la ventana de botín al despojar. Mantén Mayús al despojar para verla."
L["Exclude Warbound Containers"] = "No abrir los contenedores de banda guerrera"
L["Flashes a warning on screen when any equipped item drops below the configured durability threshold. Only triggers out of combat."] = "Muestra un aviso en pantalla cuando una pieza de equipo baja del umbral de durabilidad elegido. Solo salta fuera de combate."
L["Font size for keystone entries in the popup (does not affect the header)."] = "Tamaño de letra de las piedras angulares en la ventana (no cambia el título)."
L["GCD Circle"] = "Círculo del GCD"
L["Hide crafted items from the gear tile list.\nCrafted items cannot be upgraded at the Upgrade NPC."] = "Quita los objetos fabricados de la lista de piezas de equipo.\nLos objetos fabricados no se pueden mejorar en el PNJ de mejora."
L["Hide Item Transforms (ex: Chef's Hat)"] = "Ocultar las transformaciones de objetos (p. ej.: gorro de cocinero)"
L["Hides Blizzard's tutorial UI: the yellow HelpTip bubbles and the glowing (i) help-plate buttons on the spellbook, talents, map, collections, and other panels."] = "Oculta los tutoriales de Blizzard: las burbujas amarillas de ayuda y los botones (i) brillantes de ayuda del libro de hechizos, los talentos, el mapa, las colecciones y otros paneles."
L["Hides most red error messages (such as 'Not enough rage' or 'Ability is not ready yet'). Important errors like a full bag or quest log are still shown."] = "Oculta casi todos los mensajes de error en rojo (como «No tienes suficiente ira» o «Esa facultad todavía no está lista.»). Los errores importantes, como bolsas o registro de misiones llenos, se siguen mostrando."
L["Hides the 'Screenshot saved' notification that appears on screen after taking a screenshot."] = "Oculta el aviso de «Captura de pantalla guardada» que sale en pantalla al hacer una captura."
L["Hides the large NPC dialogue popup that appears during quests and dungeons."] = "Oculta la ventana grande de diálogo de los PNJ que sale en misiones y mazmorras."
L["Hides the Lua error popup. The same setting as Global Settings > Developer."] = "Oculta la ventana de errores de Lua. Es el mismo ajuste que Ajustes globales > Desarrollador."
L["Low Durability Warning"] = "Aviso de durabilidad baja"
L["No items queued, click tiles to add an item to queue."] = "No hay objetos en la cola; haz clic en las casillas para añadir un objeto a la cola."
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Solo muestra el círculo del cursor mientras el ratón está oculto, es decir, mientras mantienes el botón izquierdo o el derecho para girar la cámara o mover a tu personaje."
L["Portal on Cooldown"] = "Portal en reutilización"
L["Preview durability warning"] = "Vista previa del aviso de durabilidad"
L["Refresh Data"] = "Actualizar datos"
L["Refresh using tooltip scan data."] = "Actualizar con los datos de las descripciones."
L["Requires the Item Upgrade window to be open."] = "Necesita que la ventana de mejora de objetos esté abierta."
L["Rested Indicator"] = "Indicador de descanso"
L["Scale of the /keys popup window."] = "Tamaño de la ventana /keys."
L["Scan all equipped gear costs at the Item Upgrade NPC."] = "Buscar el coste de todo el equipo puesto en el PNJ de mejora de objetos."
L["Shift + Left-Click Drag to permanently save a panel's position."] = "Mayús + arrastrar con el clic izquierdo para guardar para siempre la posición de un panel."
L["Shift + Scroll to permanently zoom a panel. Ctrl + Scroll for a temporary zoom."] = "Mayús + rueda para cambiar para siempre el zoom de un panel. Ctrl + rueda para un zoom temporal."
L["Show Coordinates on Map"] = "Mostrar coordenadas en el mapa"
L["Show gear tiles for items already at their maximum item level."] = "Muestra las casillas de equipo de los objetos que ya están en su nivel de objeto máximo."
L["Show how many crests you can still earn before hitting the season cap (cap minus earned so far)."] = "Muestra cuántos emblemas puedes ganar todavía antes de llegar al límite de la temporada (el límite menos lo que llevas ganado)."
L["Show only while in a dungeon, raid, arena or battleground. Combine with Combat to show only during instanced combat."] = "Solo se ve en mazmorras, bandas, arenas o campos de batalla. Combínalo con Combate para verlo solo en combate dentro de instancias."
L["Show only while in combat. Combine with Instances to show only during instanced combat."] = "Solo se ve en combate. Combínalo con Instancias para verlo solo en combate dentro de instancias."
L["Show Tertiary Stats"] = "Mostrar estadísticas terciarias"
L["Shows a large on-screen text when you enter and/or leave combat (e.g. \"+Combat\" / \"-Combat\"). Use the cog to set the display text, size, colors and which transitions are shown; use Unlock Mode to reposition the alert."] = "Muestra un texto grande en pantalla al entrar o salir de combate (p. ej.: «+Combate» / «-Combate»). Usa el engranaje para elegir el texto, el tamaño, los colores y qué cambios se avisan; usa el modo desbloqueo para mover el aviso."
L["Show the seasonal Earned / Cap column in the crest table."] = "Muestra en la tabla de emblemas la columna de la temporada Ganado / Límite."
L["Shows a large on-screen alert (e.g. \"Player DIED!\") whenever a party or raid member dies, so you immediately notice deaths during dungeons and raids. Use Unlock Mode to reposition the alert."] = "Muestra un aviso grande en pantalla (p. ej.: «¡Jugador MUERTO!») cada vez que muere alguien del grupo o de la banda, para que te des cuenta enseguida en mazmorras y bandas. Usa el modo desbloqueo para mover el aviso."
L["Shows a popup with party and guild keystones when typing /keys."] = "Muestra una ventana con las piedras angulares del grupo y de la hermandad al escribir /keys."
L["Shows the 'Disable Feature' text below the teleport button. When off, the text is hidden and the window is 20px shorter."] = "Muestra el texto «Desactivar función» debajo del botón de teletransporte. Si lo desactivas, el texto se oculta y la ventana es 20 px más baja."
L["Skip Cinematics"] = "Saltar las cinemáticas"
L["Sort queue by crest type (cheapest first)"] = "Ordenar la cola por tipo de emblema (el más barato primero)"
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat."] = "Evita seleccionar con el clic derecho. Enemigos se aplica en todas partes. Aliados en combate solo lo evita con objetivos amistosos mientras estás en combate, para que puedas seguir haciendo clic derecho en mercaderes y PNJ fuera de combate."
L["This option is now controlled by the Raid Frames addon"] = "Esta opción la controla ahora el addon de marcos de banda"
L["This option requires a custom thickness to be set."] = "Esta opción necesita un grosor personalizado."
L["When enabled, left-click dragging a window will save its position without needing to hold Shift. Ctrl+drag still does a temporary move."] = "Si lo activas, al arrastrar una ventana con el clic izquierdo se guarda su posición sin mantener Mayús. Ctrl + arrastrar sigue moviéndola solo un rato."
L["When you join a Group Finder group for a dungeon that has a teleport, shows a small movable popup with the dungeon name and a one-click teleport button. It hides when you enter the dungeon, leave the group, or enter combat."] = "Cuando entras en un grupo del buscador de grupos para una mazmorra con teletransporte, muestra una ventana pequeña que puedes mover con el nombre de la mazmorra y un botón para teletransportarte con un clic. Se oculta al entrar en la mazmorra, salir del grupo o entrar en combate."
L["When you press Escape or Space during a cinematic, the confirmation prompt is automatically accepted."] = "Al pulsar Esc o Espacio en una cinemática, se acepta sola la pregunta de confirmación."
L["Shows the approximate distance to your current target as movable on-screen text (default 30-35). Use the cog for format, alignment, and text size; use Unlock Mode to position or Anchor to your Player Frame."] = "Muestra en pantalla la distancia aproximada a tu objetivo actual en un texto que puedes mover (predeterminado: 30-35). Usa el engranaje para el formato, la alineación y el tamaño del texto; usa el modo desbloqueo para colocarlo o anclarlo a tu marco del jugador."
L["Adds a mover for Blizzard's top-center event text and widgets (scenario, event, and encounter bars)."] = "Añade un mando para mover el texto de eventos de arriba en el centro de Blizzard y sus elementos (barras de gestas, eventos y encuentros)."
L["Hides the Top Bar Event Text mover in Unlock Mode while keeping its saved position applied."] = "Oculta en el modo desbloqueo el mando del texto de eventos de la barra superior, pero mantiene la posición guardada."
L["Shows the checked classes' mobility spell(s) counting down on cooldown. Nothing checked = feature disabled. Use Unlock Mode to reposition/resize."] = "Muestra la cuenta atrás de la reutilización de los hechizos de movilidad de las clases marcadas. Sin nada marcado, la función está desactivada. Usa el modo desbloqueo para moverlo o cambiar su tamaño."
L["Only show the alert while in combat."] = "Solo mostrar el aviso en combate."
L["Speaks the ability name once, right when it comes off cooldown -- not a running countdown. None = no speech."] = "Dice el nombre de la facultad una vez, justo cuando termina su reutilización (no es una cuenta atrás). Ninguno = no dice nada."
L["Text-to-Speech is enabled and takes priority over Sound."] = "Texto a voz está activado y tiene prioridad sobre Sonido."
L["Right-Click to set custom alert text."] = "Clic derecho para poner un texto de aviso propio."
L["Flashes a banner whenever a tracked mobility spell's cooldown is proc-reset. Use Unlock Mode to reposition/resize."] = "Muestra un rótulo cada vez que un proc reinicia la reutilización de un hechizo de movilidad seguido. Usa el modo desbloqueo para moverlo o cambiar su tamaño."
L["Warlock only. Alerts when your Gateway Control Shard is usable. Use Unlock Mode to reposition/resize."] = "Solo para brujos. Avisa cuando se puede usar tu Fragmento de control de portal. Usa el modo desbloqueo para moverlo o cambiar su tamaño."
L["Changing the /keys popup requires a reload to update slash command registration."] = "Para que el cambio de la ventana /keys se aplique al comando hay que recargar."
L["At Max (%d)"] = "Al máximo (%d)"
L["Circle Opacity"] = "Opacidad del círculo"
L["Current iLvl: %s%.1f|r     Max Possible: %s%.1f|r"] = "Nivel de objeto actual: %s%.1f|r     Máximo posible: %s%.1f|r"
L["Total Missing Upgrades: %s%d|r"] = "Mejoras que faltan en total: %s%d|r"
L["Upgradable Items (%s%d|r)"] = "Objetos mejorables (%s%d|r)"
L["(exact)"] = "(exacto)"
L["Combat Alert Settings"] = "Ajustes del aviso de combate"
L["Disable Class Color to pick a custom color."] = "Desactiva Color de clase para elegir un color personalizado."
L["Enter Class Color"] = "Color de clase al entrar"
L["Enter Color"] = "Color al entrar"
L["Enter Text"] = "Texto al entrar"
L["Enter & Leave"] = "Al entrar y al salir"
L["Enter Only"] = "Solo al entrar"
L["Leave Only"] = "Solo al salir"
L["Coin Icons"] = "Iconos de monedas"
L["Group Loot"] = "Botín de grupo"
L["Leave Class Color"] = "Color de clase al salir"
L["Leave Color"] = "Color al salir"
L["Leave Text"] = "Texto al salir"
L["Reset Shifter Positions & Zoom"] = "Restablecer las posiciones y el zoom de Shifter"
